# QUESTION: P4
# SECTION: U6. Rate of convergence of steepest descent
#
#
# Objetive:
# - compute the minimum point using steepst descent

import numpy as np
from descent import steepest_descent

if __name__=="__main__":
    def f(x): return 10*x[0]**2 + x[1]**2
    def df(x): return np.array([20*x[0], 2*x[1]])

    x0 = np.array([1, 1])

    xk, converged, x_list = steepest_descent(f, df, x0, epsilon=1e-1, k=100, debug=True)

    ### just plotting sequence of points generated by method
    import matplotlib.pyplot as plt
    x = np.linspace(-1, 2, 200)
    y = np.linspace(-1, 2, 200)
    X, Y = np.meshgrid(x, y)
    Z = f(np.array([X, Y]))          # x[0] -> X, x[1] -> Y

    cs = plt.contour(X, Y, Z, levels=[0.5, 1, 2, 4, 8])
    plt.clabel(cs, inline=True, fontsize=8)

    plt.plot(x_list[:, 0], x_list[:, 1], "o-")
    for i, x in enumerate(x_list[:10, :], start=1):
        plt.annotate(str(i), (x[0], x[1]), textcoords="offset points", xytext=(5, 5))

    plt.gca().set_aspect("equal")
    plt.savefig("P4.png")

